\begin{lemma}[Smooth Coordinate Representations]
\label{exer:2-3}




\dcref{ch2:2.3}
If $f:M\to\mathbb R^k$ is smooth and $(U,\varphi)$ is any smooth chart, then $f\circ\varphi^{-1}:\varphi(U)\to\mathbb R^k$ is smooth.
\end{lemma}

